document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.demo-mobile-menu');const n=document.getElementById('demo-nav');if(b&&n){b.addEventListener('click',()=>{const on=n.classList.toggle('show');b.setAttribute('aria-expanded',String(on));});n.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{n.classList.remove('show');b.setAttribute('aria-expanded','false');}));}});